mapper.select:
SELECT COUNT(t_sales_bidding.bidding_no)
FROM t_sales_bidding
WHERE t_sales_bidding.is_deleted = 0
  AND t_sales_bidding.user_name = #{userName}
  AND t_sales_bidding.org_no = #{orgNo}

select t_system_org.org_no_abbreviation
from t_system_org
where t_system_org.org_no = #{orgNo}

SELECT t_system_org.org_name
FROM t_system_org
WHERE t_system_org.org_no = #{orgNo}

SELECT count(t_apply_bidding.customer)
FROM t_apply_bidding
WHERE t_apply_bidding.tender_number = #{tenderNumber}

SELECT t_depot.depot_name AS depotName
FROM t_depot
WHERE t_depot.depot_no = #{depotNo}
